def build_agent(sandbox):
    # Create a grounded beam to provide structural support and guide particles
    beam = sandbox.add_beam(x=6, y=1.5, width=0.5, height=0.3, angle=0, density=250.0)
    joint = sandbox.add_joint(beam, None, (6, 0), type='rigid')  # Anchor to ground
    return beam

def agent_action(sandbox, agent_body, step_count):
    particles = sandbox.get_fluid_particles()
    for particle in particles:
        x = particle.position.x
        y = particle.position.y

        # Apply forward thrust to move particles forward
        sandbox.apply_force_to_particle(particle, 200, 0)

        # Adjust vertical position to avoid gravity well
        if 10 <= x <= 14 and 1.5 <= y <= 3.5:
            desired_y = 1.5
        else:
            desired_y = 2.5
        delta_y = desired_y - y
        sandbox.apply_force_to_particle(particle, 0, delta_y * 200)

        # Counteract gravity well force
        if 10 <= x <= 14 and 1.5 <= y <= 3.5:
            sandbox.apply_force_to_particle(particle, 0, 200)

        # Avoid pits by applying escape forces
        if (13.5 <= x <= 15.5 and 0 <= y <= 2) or \
           (16 <= x <= 17.5 and 0 <= y <= 1.6) or \
           (11 <= x <= 12.5 and 0 <= y <= 1.6):
            if x < 13.5:
                force_x = -200
            elif x > 15.5:
                force_x = 200
            elif x < 16:
                force_x = -200
            elif x > 17.5:
                force_x = 200
            elif x < 12.5:
                force_x = -200
            else:
                force_x = 0
            sandbox.apply_force_to_particle(particle, force_x, 0)

        # Stop particles in target zone
        if 18 <= x <= 22 and 0 <= y <= 1.5:
            # No force applied to stop particles in target
            pass
